import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易附录纂注卷十二","description":"易附录纂注 - 易附录纂注卷十二","frontmatter":{"title":"易附录纂注卷十二","description":"易附录纂注 - 易附录纂注卷十二"},"headers":[],"relativePath":"zh/classics/yifulu-zuanzhu/013.md","filePath":"zh/classics/yifulu-zuanzhu/013.md"}'),r={name:"zh/classics/yifulu-zuanzhu/013.md"};function i(c,a,o,u,d,p){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附录纂注卷十二",tabindex:"-1"},[n("易附录纂注卷十二 "),e("a",{class:"header-anchor",href:"#易附录纂注卷十二","aria-label":"Permalink to “易附录纂注卷十二”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"元胡一桂撰总论杂卦 杂卦反对之义，只是反复，则其吉凶、祸福、动静、刚柔皆相反了。答虞大中。",-1),e("p",null,"乾刚坤柔。附录。 刚柔虽各有所偏，必相错而后得中。然在乾、坤二卦之全体，当刚而刚，当柔而柔，则不待相错而不害其全矣。其爻位之无过不及者，如乾、坤之二五，亦不待相错而不害其为中矣。阴阳变化，而太极之妙无不在焉，于此盖可见也。今谓「乾刚坤柔」，便有所偏，恐于二卦之彖及二五之爻有不通者。答虞大中。 「比乐师忧」，临、观之义，或与或求。 以我临物曰「与」，物来观我曰「求」。或曰：二卦互有「与」「求」之义。 附录。 「临」、观更有「与」「求」之义。「临」，以二阳言之，则二阳可以临上四阴。以卦中爻言之，则六五、上六又以上而临下。「观」，自下而观上则为观，是平声；自上而为物之观。是去声。道夫。 屯见而不失其居，蒙杂而著。 「屯」，震遇坎，震动故见坎险不行也。「蒙」，坎遇艮，坎幽昧，艮光明也。或曰「屯」以初言，「蒙」以二言。 纂注：蔡氏曰：屯，物之始生，故见主初也未得位而利居贞，故不失其居。蒙然而生，故「杂」。二为蒙主，而能治之使明，故著。 震，起也；「艮」，止也。损、益，盛衰之始也。纂注：蔡氏曰：「震阳起于下，艮阳止于上。损者，盛之始，益者，衰之始。」 大畜，时也；无妄，灾也。 止健者，时有适然。无妄而灾自外至。 纂注：蔡氏曰：「刚健者难畜，当刚止之时，故能畜，莫非灾也。无妄之灾，乃所谓灾也。」 萃聚而升不来也。纂注：蔡氏曰：「泽聚而下，木升而上。」 谦轻而豫怠也。附录：谦轻是自谦抑，不自尊重。道夫轻是自卑小之义，说豫之极，便放倒了，如上文「冥豫」是也。去伪。 噬嗑，食也；贲，无色也， 白受采。 纂注：蔡氏曰：「颐中有物，故食。贲则其色不常，故无色。」 兑见而巽伏也。 兑阴外见，巽阴内伏。 随，无故也，蛊则饬也。 随前无故，蛊后当饬。 剥，烂也；复，反也。纂注：蔡氏曰：「剥则阳烂，复则阳反。」 晋，昼也；明夷，诛也。 诛，伤也。 纂注：蔡氏曰：「晋离在上而明著，夷，离在下而明伤。」 井通，而困相遇也。 刚柔相遇而刚见揜也。 纂注：蔡氏曰：「井往而不穷，故为通。」困，刚掩也，刚与柔相遇也。 咸，速也；恒，久也。 咸，速；恒，久。 纂注：蔡氏曰：「有感则应，故速；常，故能久。」 涣，离也；节，止也。纂注：蔡氏曰：「风散水，故离，泽防水故止。」 解，缓也；蹇，难也。附录：散缓意，如纵弛之类。道夫、 睽，外也；家人，内也；否、泰，反其类也。大壮则止，遁则退也。 止谓不退。 纂注：蔡氏曰：「大壮阴止，遁阳退。」徐氏曰：「杂卦言止者三：艮，止也，谓阳升于上，止而不进，天之道也。节，止也，谓有所限节而遏止之，人之力也。大壮则止，谓四阳方壮，止而不退，亦天道也。」 大有，众也；同人，亲也。革，去故也；鼎，取新也。小过，过也；中孚，信也。纂注：蔡氏曰：「莫非过也，小过之过，乃所谓过也。小者能过，岂常理哉！莫非信也，中孚之信，乃所谓信也。信出于中，岂要约之所能致哉！」 丰，多故也；亲寡，旅也。 既明且动，其故多矣。 离上而坎下也。 火炎上，水润下。 小畜，寡也；履，不处也。 不处，行进之义。 需，不进也；讼，不亲也；大过，颠也。纂注：徐氏曰：「本末弱，故颠。」 姤，遇也，柔遇刚也。渐，女归待男行也。附录：女待男而行，所以为渐。渊。 颐，养正也；既济，定也。纂注：蔡氏曰：「六位皆当，故定。」 归妹，女之终也；未济，男之穷也。附录：伊川说未济男之穷，为三阳失位，以为斯义也得之成都隐者。见张钦夫说伊川之在涪也，一日读易，有刳桶人以此问伊川，伊川不能答。其人云：「三阳失位，故伊川记之。」不知此语火珠林上已有。盖伊川未尝看杂书，所以被他说动了。渊。 夬，决也，刚决柔也。君子道长，小人道忧也。 自姤以下，卦不反对，或疑其错简，今以韵协之，又似非误，未详何义。 纂注。 蔡氏曰：「自姤以下有乱简。」按杂卦例皆反对协韵为序，今以其例改正。大过，颠也；颐，养正也；既济，定也。未济，男之穷也。归妹，女之终也。渐，女归待男行也。姤，遇也，柔遇刚也。夬，决也，刚决柔也，君子道长，小人道忧也。愚谓杂卦以乾为首，不终之以他卦，而必终之以夬者，盖夬以五阳决一阴，决去一阴，则复为乾矣，故曰「君子道长，小人道忧也」。易为君子谋，大哉言矣！ 易附录纂注卷十二。",-1)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
